function parseThreshold(thresholdStr: string): { metric: string; min: number } {
  const parts = thresholdStr.split('=');
  if (parts.length !== 2) {
    throw new Error(`Invalid threshold format: "${thresholdStr}". Expected format: <metric>=<value>`);
  }
  const [metric, valueStr] = parts;
  const min = Number.parseFloat(valueStr);
  if (Number.isNaN(min)) {
    throw new Error(`Invalid threshold value: "${valueStr}". Must be a number between 0 and 1.`);
  }
  if (min < 0 || min > 1) {
    throw new Error(`Invalid threshold value: ${min}. Must be between 0 and 1.`);
  }
  return { metric: metric.trim(), min };
}

function buildThresholdsMap(thresholdStrs?: string[]): Record<string, number> | undefined {
  if (!thresholdStrs || thresholdStrs.length === 0) {
    return undefined;
  }
  const thresholds: Record<string, number> = {};
  thresholdStrs.forEach((str) => {
    const { metric, min } = parseThreshold(str);
    if (!thresholds[metric]) {
      thresholds[metric] = min;
    }
  });
  return thresholds;
}

function validateThresholds(thresholds: Record<string, number>, evaluations: any[]): { valid: boolean; errors: string[] } {
  const errors: string[] = [];
  const validMetrics = new Set(evaluations.map((m) => m.id));

  Object.keys(thresholds).forEach((metricId) => {
    if (!validMetrics.has(metricId)) {
      errors.push(`Unknown metric: "${metricId}"`);
    }
  });

  if (errors.length > 0) {
    const validList = Array.from(validMetrics).join(', ');
    errors.push(`Valid metrics: ${validList}`);
  }

  return { valid: errors.length === 0, errors };
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);

  let thresholds: Record<string, number> | undefined;
  try {
    thresholds = buildThresholdsMap(options.threshold);
  } catch (error) {
    log.error('Threshold error.', {
      error: error instanceof Error ? error.message : String(error)
    });
    process.exit(2);
  }

  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  if (thresholds) {
    const validation = validateThresholds(thresholds, evaluations);
    if (!validation.valid) {
      log.error('Invalid thresholds.', {
        errors: validation.errors
      });
      validation.errors.forEach((err) => {
        console.error(` - ${err}`);
      });
      process.exit(2);
    }
  }

  const result = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds
  });

  const report = result.report;
  const passed = result.passed;

  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  if (thresholds && !passed) {
    process.exit(1);
  }
}

