    const result = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: { exact_match: 0.9 }
    });
    expect(result.passed).toBe(false);
    expect(result.report.passed).toBe(false);
    expect(result.report.thresholds[0].passed).toBe(false);
  });

  it('handles missing scores with null', () => {
    const evaluations = [
      {
        id: 'exact_match',
        label: 'Exact Match',
        score: null,
        total: 0,
        matches: 0,
        details: 'No references provided'
      }
    ];
    const result = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: null,
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: { exact_match: 0.8 }
    });
    expect(result.passed).toBe(false);
    expect(result.report.thresholds[0]).toMatchObject({
      score: null,
      passed: false
    });
  });

  it('maintains backward compatibility without thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
    expect(report.passed).toBeUndefined();
    expect(report.thresholds).toBeUndefined();
    expect(report.metadata).toBeDefined();
    expect(report.metrics).toBeDefined();
  });
});

