export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  let passed = true;
  const thresholdResults = [];

  if (thresholds) {
    Object.entries(thresholds).forEach(([metricId, min]) => {
      const metric = evaluations.find((m) => m.id === metricId);
      const metricPassed = metric && metric.score !== null && metric.score >= min;
      if (!metricPassed) passed = false;
      thresholdResults.push({
        metric: metricId,
        min,
        score: metric?.score ?? null,
        passed: Boolean(metricPassed)
      });
    });

    report.passed = passed;
    report.thresholds = thresholdResults;

    return { report, passed };
  }

  return report;
}

