  .option('--report <path>', 'Report path (default: frai-eval-report.json)')
  .option('--format <format>', 'Report format (json or markdown)', 'json')
  .option('--threshold <metric>=<value>', 'Quality gate: metric minimum score (0-1, repeatable; e.g., --threshold exact_match=0.9 --threshold bleu=0.8)', (value, previous) => {
    return [...(Array.isArray(previous) ? previous : []), value];
  }, [])
  .action((options: EvalOptions & { threshold: string[] }) => {
    runEvalCommand({ ...options, threshold: options.threshold });
  });

